<?php use App\Models\Ticket; foreach($listOrder as $column): switch($column):case 'type': ?><td data-column="type" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?= work_mark('type',$t['type'],(int)$t['project_id']) ?></td><?php break; case 'key': ?><td data-column="key" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><a class="ticket-key" href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['key']) ?></a></td><?php break; case 'title': ?><td class="title-cell" data-column="title" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><div class="ticket-title-line"><?php if(!empty($filters['hierarchy'])&&!empty($childrenByParent[$t['id']])): ?><button class="tiny-button" data-toggle-children="<?= (int)$t['id'] ?>" aria-expanded="true" aria-label="Afficher ou masquer les tickets enfants">⌄</button><?php endif; ?><?php if(!empty($filters['hierarchy'])&&$t['parent_id']): ?><span class="hierarchy-indent">↳</span><?php endif; ?><a href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['title']) ?></a><?= blocked_badge((bool)$t['flagged']) ?><button class="inline-edit" data-edit-field="title" data-value="<?= e($t['title']) ?>" aria-label="Modifier le résumé">✎</button></div><div class="ticket-progress" <?= ($filters['show_progress']??'1')==='0'?'hidden':'' ?> data-column="progress_percent" title="Reste à faire calculé sur l’estimation totale et l’avancement"><div class="ticket-progress-meter"><progress value="<?= (int)$t['progress_percent'] ?>" max="100" aria-label="<?= e('Avancement de '.$t['key']) ?>" data-progress-meter><?= (int)$t['progress_percent'] ?> %</progress><span data-progress-percent aria-hidden="true"><?= (int)$t['progress_percent'] ?> %</span></div><small data-progress-remaining><?= $t['remaining_hours']===null?'Estimation manquante':'≈ '.e(App\Core\View::hours($t['remaining_hours'])).' restantes' ?></small></div></td><?php break; case 'assignee': ?><td data-column="assignee" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><select class="cell-select" data-quick-field="assignee_id" aria-label="Personne assignée pour <?= e($t['key']) ?>"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $t['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></td><?php break; case 'team': ?><td data-column="team" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?= e($t['team_name']??'Sans équipe') ?></td><?php break; case 'priority': ?><td data-column="priority" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><div class="cell-priority"><?= work_mark('priority',$t['priority']) ?><select class="cell-select" data-quick-field="priority" aria-label="Priorité pour <?= e($t['key']) ?>"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></div></td><?php break; case 'status': ?><td data-column="status" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><select class="status-select workflow-status" data-status-color="<?= e($t['status_color']) ?>" data-quick-field="status" title="<?= e($t['status_label']) ?>" aria-label="État pour <?= e($t['key']) ?>"><?php foreach($t['status_options'] as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></td><?php break; case 'due': ?><td data-column="due" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?php if($t['due_date']): ?><time datetime="<?= e($t['due_date']) ?>"><?= e(date('d/m/Y',strtotime($t['due_date']))) ?></time><?php else: ?><span class="muted">—</span><?php endif; ?></td><?php break; case 'estimated_hours': ?><td data-column="estimated_hours" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><span class="ticket-estimate-value"><?= $t['estimated_hours']===null?'—':e(App\Core\View::hours($t['estimated_hours'])) ?></span></td><?php break; case 'labels': ?><td data-column="labels" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?php foreach($t['labels_array'] as $label): ?><span class="label-tag"><?= e($label) ?></span><?php endforeach; ?></td><?php break; case 'created': ?><td data-column="created" <?= in_array($column,$listColumns,true)?'':'hidden' ?> class="muted"><?= e(substr($t['created_at'],0,10)) ?></td><?php break; endswitch; endforeach; ?>